#include "lis.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
static LIS_MATRIX load(char *path){FILE *f=fopen(path,"rb"); if(!f)exit(11); int n,z; if(fread(&n,4,1,f)!=1||fread(&z,4,1,f)!=1)exit(12); LIS_INT *p=lis_malloc((n+1)*sizeof(*p),"row"),*j=lis_malloc(z*sizeof(*j),"col"); LIS_SCALAR *v=lis_malloc(z*sizeof(*v),"val"); if(sizeof(LIS_INT)!=4||sizeof(LIS_SCALAR)!=8)exit(13); if(fread(p,4,n+1,f)!=n+1||fread(j,4,z,f)!=z||fread(v,8,z,f)!=z)exit(14);fclose(f);LIS_MATRIX M;lis_matrix_create(0,&M);lis_matrix_set_size(M,0,n); if(lis_matrix_set_csr(z,p,j,v,M)||lis_matrix_assemble(M))exit(15);return M;}
int main(int argc,char **argv){if(argc<5)return 10;lis_initialize(&argc,&argv);LIS_MATRIX A=load(argv[1]),B=load(argv[2]);LIS_VECTOR x;LIS_ESOLVER e;lis_vector_duplicate(A,&x);lis_esolver_create(&e);lis_esolver_set_option("-eprint none",e);int rc=lis_esolver_set_optionC(e);if(rc){printf("CONFIG %d\n",rc);return 20;} const char *opts=getenv("LIS_BENCH_LINEAR");if(opts){rc=lis_esolver_set_linear_options(opts,e);if(rc){printf("LINEAR CONFIG %d\n",rc);return 21;}} const char *basis=getenv("LIS_BENCH_MODES"); if(basis){ FILE *mf=fopen(basis,"rb");LIS_VECTOR v[3]={0};int i;if(!mf)return 22;for(i=0;i<3;i++){if(lis_vector_duplicate(A,&v[i]))return 23;if(fread(v[i]->value,8,A->n,mf)!=A->n)return 24;}fclose(mf);rc=lis_esolver_set_inner_near_nullspace(e,3,v);for(i=0;i<3;i++)lis_vector_destroy(v[i]);if(rc){printf("BASIS CONFIG %d\n",rc);return 25;}puts("BASIS registered three trial vectors with public prototype API; caller storage destroyed");} int m=e->options[LIS_EOPTIONS_ESOLVER]; LIS_SCALAR lam=NAN;printf("BEGIN method=%d n=%d\n",m,A->n);fflush(stdout);double t=lis_wtime();rc=lis_gesolve(A,B,x,&lam,e);t=lis_wtime()-t;int status=-1,iter=-1;double tm=0,it=0,pt=0,pc=0,pi=0;LIS_REAL res=NAN;lis_esolver_get_status(e,&status);lis_esolver_get_iter(e,&iter);lis_esolver_get_timeex(e,&tm,&it,&pt,&pc,&pi);lis_esolver_get_residualnorm(e,&res);printf("RESULT rc=%d status=%d iter=%d wall=%.9g solver=%.9g inner=%.9g precon=%.9g setup=%.9g lambda=%.17g residual=%.17g\n",rc,status,iter,t,tm,it,pt,pc,(double)lam,(double)res);fflush(stdout);FILE *f=fopen(argv[3],"wb");if(f){if(m==14||m==15||m==16||m==17||m==18){for(int i=0;i<e->evector_owned_count;i++){LIS_SCALAR l; if(lis_esolver_get_specific_evalue(e,i,&l)||lis_esolver_get_specific_evector(e,i,x))break;fwrite(&l,8,1,f);fwrite(x->value,8,A->n,f);}}else if(isfinite(lam)){fwrite(&lam,8,1,f);fwrite(x->value,8,A->n,f);}fclose(f);}return 0;}
